import { useMemo, useLayoutEffect, useRef } from 'react';
import { useGLTF } from '@react-three/drei';
import * as THREE from 'three';
import { SkeletonUtils } from 'three-stdlib';

// ============================================================================
// THE SKINNED WIZARD
//
// Loads the character generated by tools/build_wizard.py — a single continuous
// mesh bound to a 24-bone skeleton — and exposes its bones by name so the
// existing spring rig can drive them.
//
// This replaces a hierarchy of capsules and spheres. The difference is not
// detail, it is CONTINUITY: primitives never merge into one surface, so the
// figure always read as parts assembled into a mannequin. A skinned mesh
// deforms across the joints the way skin does.
//
// BIND POSE MATTERS. A glTF skeleton's bones already carry the rotation that
// puts them in their rest pose. Assigning `bone.rotation.set(...)` throws that
// away and collapses the character. Every pose here is therefore applied as a
// DELTA composed onto the captured bind quaternion.
// ============================================================================

const MODEL_URL = `${import.meta.env.BASE_URL || '/'}wizard.glb`.replace('//', '/');

export function useWizardModel() {
  const gltf = useGLTF(MODEL_URL);

  // Clone per instance: the same glTF may back several characters, and a
  // SkinnedMesh cannot be shared because each needs its own skeleton pose.
  // SkeletonUtils.clone is the only clone that rebinds skinning correctly.
  const scene = useMemo(() => SkeletonUtils.clone(gltf.scene), [gltf.scene]);

  const { bones, bind } = useMemo(() => {
    const b = {};
    const bindMap = new Map();
    scene.traverse((o) => {
      if (o.isBone) {
        b[o.name] = o;
        bindMap.set(o.name, o.quaternion.clone());
      }
      if (o.isMesh || o.isSkinnedMesh) {
        o.castShadow = true;
        o.receiveShadow = true;
        o.frustumCulled = false;   // skinned bounds are computed at bind pose
      }
    });
    return { bones: b, bind: bindMap };
  }, [scene]);

  return { scene, bones, bind };
}

// Compose a local euler onto a bone's bind rotation.
const _e = new THREE.Euler();
const _q = new THREE.Quaternion();
export function poseBone(bone, bindQuat, x = 0, y = 0, z = 0, order = 'XYZ') {
  if (!bone || !bindQuat) return;
  _e.set(x, y, z, order);
  _q.setFromEuler(_e);
  bone.quaternion.copy(bindQuat).multiply(_q);
}

useGLTF.preload(MODEL_URL);
